import math

def avg_nll(theta, heads, n, unit):
    """Average negative log-likelihood of heads in n tosses, in "bits" or "nats"."""
    nats = -(heads * math.log(theta) + (n - heads) * math.log(1 - theta)) / n
    return nats / math.log(2) if unit == "bits" else nats

def best_theta(heads, n):
    """The theta in 0.01, 0.02, ..., 0.99 with the least average loss."""
    grid = [k / 100 for k in range(1, 100)]
    return min(grid, key=lambda th: avg_nll(th, heads, n, "nats"))
